#!/usr/bin/env python3
"""Audit services against SPEC.md rev 7. Writes findings/svc-XX.json."""
import ast
import json
import re
from pathlib import Path

ROOT = Path('/private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/f4c9cb678e78')
SERVICES = ROOT / 'services'
FINDINGS = ROOT / 'findings'
LFS_FIRST = 'version https://git-lfs.github.com/spec/v1'

def is_lfs_pointer(path):
    try:
        with path.open('rb') as fh:
            return fh.readline().decode('utf-8', 'replace').rstrip('\r\n') == LFS_FIRST
    except OSError:
        return False

def any_lfs(service_dir):
    return any(is_lfs_pointer(p) for p in service_dir.rglob('*') if p.is_file())

def load_json(path):
    try:
        return json.loads(path.read_text())
    except Exception:
        return {}

def parse_py(path):
    try:
        return ast.parse(path.read_text(), filename=str(path))
    except Exception:
        return None

def py_files(service_dir):
    return sorted((service_dir / 'src').rglob('*.py')) if (service_dir / 'src').is_dir() else []

def string_constants(tree):
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            yield node.value
        elif isinstance(node, ast.Constant) and isinstance(node.value, bytes):
            try:
                yield node.value.decode('utf-8')
            except UnicodeDecodeError:
                pass

def print_calls(tree):
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'print':
            yield node

def handler_names(tree):
    names = set()
    if tree is None:
        return names
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            names.add(node.name)
    return names

def has_docstring(node):
    try:
        body = node.body
        return bool(body) and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str)
    except Exception:
        return False

def audit(service_dir):
    name = service_dir.name
    if any_lfs(service_dir):
        return {'service': name, 'status': 'unverifiable', 'violations': [], 'details': ['LFS pointer']}
    config = load_json(service_dir / 'config.json')
    dockerfile_path = service_dir / 'Dockerfile'
    dockerfile = dockerfile_path.read_text() if dockerfile_path.is_file() else ''
    readme_path = service_dir / 'README.md'
    readme = readme_path.read_text() if readme_path.is_file() else ''
    codeowners_path = service_dir / 'CODEOWNERS'
    codeowners = codeowners_path.read_text() if codeowners_path.is_file() else ''
    requirements_path = service_dir / 'requirements.txt'
    requirements = requirements_path.read_text() if requirements_path.is_file() else ''
    handlers_path = service_dir / 'src' / 'handlers.py'
    handlers_tree = parse_py(handlers_path) if handlers_path.is_file() else None
    src_trees = [(p, parse_py(p)) for p in py_files(service_dir)]

    violations = []
    details = {}

    public = config.get('exposure') == 'public'

    # C1
    timeout = config.get('timeout_s')
    c1 = (not public) or (isinstance(timeout, (int, float)) and not isinstance(timeout, bool) and timeout <= 30)
    details['C1'] = {'public': public, 'timeout_s': timeout}

    # C2
    c2 = True
    bad_doc = []
    if handlers_tree is not None:
        for node in ast.walk(handlers_tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith('handle_'):
                if not has_docstring(node):
                    bad_doc.append(node.name)
    c2 = not bad_doc
    details['C2'] = {'bad': bad_doc}

    # C3
    bad_print = []
    for p, tree in src_trees:
        if tree is None:
            continue
        for node in print_calls(tree):
            bad_print.append(f'{p.relative_to(service_dir)}:{node.lineno}')
    details['C3'] = {'calls': bad_print}

    # C4
    retries = config.get('retries')
    c4 = isinstance(retries, int) and not isinstance(retries, bool) and 1 <= retries <= 5
    details['C4'] = {'retries': retries}

    # C5
    from_lines = []
    for line in dockerfile.splitlines():
        m = re.match(r'^\s*FROM\s+(.*)$', line, re.IGNORECASE)
        if m:
            from_lines.append(m.group(1).strip())
    bad_from = []
    from_re = re.compile(r'@sha256:[0-9a-f]{64}$')
    for content in from_lines:
        # drop trailing comment
        content = re.sub(r'\s+#.*$', '', content).strip()
        toks = content.split()
        toks = [t for t in toks if not t.startswith('--')]
        image = toks[0] if toks else ''
        if not from_re.search(image):
            bad_from.append(content)
    c5 = bool(from_lines) and not bad_from
    details['C5'] = {'from': from_lines, 'bad': bad_from}

    # C6
    users = []
    for line in dockerfile.splitlines():
        m = re.match(r'^\s*USER\s+(.*)$', line, re.IGNORECASE)
        if m:
            val = re.sub(r'\s+#.*$', '', m.group(1)).strip()
            users.append(val)
    last_user = users[-1] if users else None
    c6 = False
    if last_user is not None:
        user_part = last_user.split(':', 1)[0].strip().lower()
        c6 = user_part not in ('root', '0')
    details['C6'] = {'users': users, 'last': last_user}

    # C7
    c7 = any(line == '## Runbook' for line in readme.splitlines())
    details['C7'] = {'ok': c7}

    # C8
    expected_owner = '@team-' + str(config.get('team', ''))
    star_owners = []
    for raw in codeowners.splitlines():
        line = raw.split('#', 1)[0].strip()
        if not line:
            continue
        parts = line.split()
        if parts and parts[0] == '*':
            star_owners.extend(parts[1:])
    c8 = expected_owner in star_owners
    details['C8'] = {'expected': expected_owner, 'star_owners': star_owners}

    # C9
    bad_strings = []
    for p, tree in src_trees:
        if tree is None:
            continue
        for s in string_constants(tree):
            if s.startswith('sk_live_') or s.startswith('AKIA'):
                bad_strings.append(f'{p.relative_to(service_dir)}: {s[:20]}')
    details['C9'] = {'bad': bad_strings}

    # C10
    healthcheck = config.get('healthcheck')
    c10 = False
    if isinstance(healthcheck, str) and healthcheck:
        path = healthcheck.split('?', 1)[0].split('#', 1)[0].rstrip('/')
        segment = path.rsplit('/', 1)[-1]
        expected_handler = 'handle_' + segment
        c10 = expected_handler in handler_names(handlers_tree)
        details['C10'] = {'healthcheck': healthcheck, 'expected': expected_handler}
    else:
        details['C10'] = {'healthcheck': healthcheck, 'expected': None}

    # C11
    c11 = ('port' in config and 'metrics_port' in config and config.get('metrics_port') != config.get('port'))
    details['C11'] = {'port': config.get('port'), 'metrics_port': config.get('metrics_port')}

    # C12
    bad_req = []
    for raw in requirements.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        # remove inline comment introduced by whitespace + #
        line = re.sub(r'\s+#.*$', '', line).strip()
        if not line:
            continue
        m = re.match(r'^[A-Za-z0-9][A-Za-z0-9._-]*(?:\[[^\]]+\])?\s*==\s*([^=<>!~;,\s]+)(?:\s*;.*)?$', line)
        if not m or '*' in m.group(1):
            bad_req.append(raw.strip())
    c12 = not bad_req
    details['C12'] = {'bad': bad_req}

    # C13
    log_level = config.get('log_level')
    c13 = log_level != 'DEBUG'
    details['C13'] = {'log_level': log_level}

    # C14
    max_body = config.get('max_body_kb')
    c14 = (not public) or (isinstance(max_body, (int, float)) and not isinstance(max_body, bool) and max_body <= 1024)
    details['C14'] = {'public': public, 'max_body_kb': max_body}

    # C15
    tests_dir = service_dir / 'tests'
    test_files = sorted(p.name for p in tests_dir.glob('test_*.py') if p.is_file()) if tests_dir.is_dir() else []
    c15 = bool(test_files)
    details['C15'] = {'files': test_files}

    results = {'C1': c1, 'C2': c2, 'C3': c3 if 'c3' in locals() else True,
               'C4': c4, 'C5': c5, 'C6': c6, 'C7': c7, 'C8': c8,
               'C9': not bad_strings, 'C10': c10, 'C11': c11, 'C12': c12,
               'C13': c13, 'C14': c14, 'C15': c15}
    # C3 assignment is bad_print, fix explicitly
    results['C3'] = not bad_print
    violations = [f'C{i}' for i in range(1, 16) if not results[f'C{i}']]
    return {'service': name, 'status': 'compliant' if not violations else 'violations',
            'violations': violations, 'details': details}

def main():
    FINDINGS.mkdir(exist_ok=True)
    reports = []
    for service_dir in sorted(SERVICES.iterdir()):
        if not service_dir.is_dir() or not service_dir.name.startswith('svc-'):
            continue
        r = audit(service_dir)
        details = r.pop('details')
        out = {'service': r['service'], 'status': r['status'], 'violations': r['violations']}
        (FINDINGS / (r['service'] + '.json')).write_text(json.dumps(out, indent=2) + '\n')
        reports.append((r, details))
    for r, details in reports:
        print(f"{r['service']}: {r['status']} {r['violations']}")
        for cid in r['violations']:
            print('   ', cid, details.get(cid))

if __name__ == '__main__':
    main()
